// The home-screen icon: a bansuri against a sunrise, drawn pixel by pixel.
//
// Rendered in code rather than exported from a design tool so the icon can be
// regenerated by anyone with Node — same reasoning as the committed corpus.
// Writes public/icons/icon-{512,192,180}.png (180 is the apple-touch-icon).
//
// The flute stays inside the central ~80% of the square, which is the safe
// zone for maskable icons — Android crops the outside into a circle or squircle
// and anything near the edge is lost.
//
// No dependencies: the PNG is assembled by hand (IHDR/IDAT/IEND + CRC32) and
// compressed with node's own zlib.

import { deflateSync } from "node:zlib";
import { mkdir, writeFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "public", "icons");

// The page's own palette (public/m.html :root) so the icon looks like the app.
const MARIGOLD = [0xfb, 0xbf, 0x24];
const ORANGE = [0xf9, 0x73, 0x16];
const ORANGE_DEEP = [0xea, 0x58, 0x0c];
const CREAM = [0xff, 0xf8, 0xf1];
const INK = [0x2f, 0x1b, 0x0e];
const AMBER = [0xd9, 0x77, 0x06];

const lerp = (a, b, t) => a + (b - a) * t;
const mix = (c1, c2, t) => c1.map((v, i) => lerp(v, c2[i], t));
const clamp01 = (t) => Math.max(0, Math.min(1, t));

function draw(size) {
  const px = Buffer.alloc(size * size * 3);

  // The flute: one diagonal segment, in unit coordinates.
  const ax = 0.22, ay = 0.78, bx = 0.78, by = 0.22;
  const dx = bx - ax, dy = by - ay;
  const len2 = dx * dx + dy * dy;
  const halfWidth = 0.072;
  const aa = 1.5 / size; // ~1.5px of anti-aliasing at every edge

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const u = (x + 0.5) / size;
      const v = (y + 0.5) / size;

      // Sunrise: marigold low, deepening orange toward the top corners.
      const d = Math.hypot(u - 0.5, v - 0.95);
      const t = clamp01(d / 1.0);
      let c = t < 0.55 ? mix(MARIGOLD, ORANGE, t / 0.55) : mix(ORANGE, ORANGE_DEEP, (t - 0.55) / 0.45);

      // Where is this pixel relative to the flute's axis?
      const s = clamp01(((u - ax) * dx + (v - ay) * dy) / len2); // 0..1 along it
      const cx = ax + s * dx, cy = ay + s * dy;
      const dist = Math.hypot(u - cx, v - cy); // distance from the axis
      const body = clamp01((halfWidth - dist) / aa); // 1 inside, 0 outside

      if (body > 0) {
        // A rounded rod: ivory, shaded darker toward the lower edge.
        const perp = dist / halfWidth;
        const below = (u - cx) * dy - (v - cy) * dx < 0 ? 1 : 0.35;
        let flute = mix(CREAM, AMBER, 0.42 * perp * perp * below);

        // The thread wrapping near each end of a bansuri.
        for (const bandAt of [0.075, 0.925]) {
          const band = clamp01((0.018 - Math.abs(s - bandAt)) / aa);
          flute = mix(flute, AMBER, 0.65 * band);
        }

        // Finger holes along the axis.
        for (const holeAt of [0.3, 0.42, 0.54, 0.66]) {
          const hx = ax + holeAt * dx, hy = ay + holeAt * dy;
          const hole = clamp01((0.021 - Math.hypot(u - hx, v - hy)) / aa);
          flute = mix(flute, INK, 0.85 * hole);
        }

        c = mix(c, flute, body);
      }

      const o = (y * size + x) * 3;
      px[o] = Math.round(c[0]);
      px[o + 1] = Math.round(c[1]);
      px[o + 2] = Math.round(c[2]);
    }
  }
  return px;
}

// ── PNG assembly ────────────────────────────────────────────────────────────

const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});

function crc32(buf) {
  let c = 0xffffffff;
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, "ascii");
  data.copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
}

function png(size, px) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: RGB — icons are full-bleed, nothing is transparent

  // Each scanline gets a leading filter byte (0 = none).
  const raw = Buffer.alloc(size * (size * 3 + 1));
  for (let y = 0; y < size; y++) {
    px.copy(raw, y * (size * 3 + 1) + 1, y * size * 3, (y + 1) * size * 3);
  }

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

await mkdir(OUT_DIR, { recursive: true });
for (const size of [512, 192, 180]) {
  const file = join(OUT_DIR, `icon-${size}.png`);
  await writeFile(file, png(size, draw(size)));
  console.log(`wrote ${file}`);
}
